/* ❌ OLD: In HSL, equal lightness steps are NOT perceptually equal.
   The mid tones look different in brightness even though the numbers
   step evenly, so you hand-tune every stop. */

:root {
  --c-300: hsl(210 80% 70%); /* looks washed out */
  --c-400: hsl(210 80% 60%);
  --c-500: hsl(210 80% 50%); /* the 'brand' color */
  --c-600: hsl(210 80% 40%);
  --c-700: hsl(210 80% 30%); /* ❌ OLD: visually jumps more than the top steps */
}

/* Each step required manual eyeballing; the ramp is uneven and
   gradients between complementary colors pass through grey mud. */

/* ✅ NEW: In OKLCH, stepping L by a constant amount looks like an even
   brightness ramp, so you can generate a whole palette numerically. */

:root {
  --c-300: oklch(75% 0.13 250); /* ✅ NEW: 10% perceptual steps */
  --c-400: oklch(65% 0.14 250);
  --c-500: oklch(55% 0.16 250); /* the brand color */
  --c-600: oklch(45% 0.14 250);
  --c-700: oklch(35% 0.12 250);
}

/* Gradients also stay vivid:
   background: linear-gradient(in oklch, var(--c-400), var(--c-600));
   No grey mud, no hand-tuning, wide-gamut friendly. */
